#include <bits/stdc++.h>
using namespace std;
#define int long long


signed main() {
	// your code goes here
    int t; cin >> t;
    while(t--){
        int n; cin >> n;
        std::vector<int> a(3*n) ;
        for(auto& x : a) cin >> x;
        sort(a.begin(), a.end());
        vector<int>pref2(3*n);
        pref2[0] = a[0];
        for(int i = 1; i < 3*n; i++) pref2[i] = pref2[i-1] + a[i];
        auto pref = [&](int x){
            if(x < 0) return 0LL;
            else return pref2[x];
        };
        int maxl = 0;
        for(int x = 0; x <= n; x++){
            int tmaxl = pref(3*n - 1) - pref(3*n - x - 1);
            tmaxl *= 6;
            
            int lo = 1, hi = n - x;
            int res = -1;
            while(lo <= hi){
                int mid = (lo + hi)/2;
                int z = mid;
                int y = n-x-z;
                
                if(a[3*n - x - 2*y-1] + a[3*n-x-2*y-2] > 3*a[3*n-2*y-3*z - x]){
                    hi = mid - 1;
                    res = mid;
                }
                else lo = mid + 1;
            }
            // cout << res << '\n';
            int z = (res == -1 ? n-x : res-1);
            
            int y = n - x - z;
            // cout << x <<" " << y << " " << z << "\n";
            int tmaxl2 = 4*(pref(3*n-x-1)-pref(3*n-x-2*y-1));
            int tmaxl3 = 3*(pref(3*n-x-2*y-1)-pref(3*n-x-2*y-3*z-1));
            tmaxl += tmaxl2+tmaxl3;
            // cout << tmaxl2 << " " << tmaxl3 << " " << tmaxl-tmaxl2-tmaxl3 <<endl;
            maxl = max(maxl, tmaxl);
            
            
        }
        
        cout << maxl << '\n';
    }
}
